function Invoke-Tangle($a) {
  if ($a -eq 1) { $x = 1 }
  if ($a -eq 2) { $x = 2 }
  if ($a -eq 3) { $x = 3 }
  if ($a -eq 4) { $x = 4 }
  if ($a -eq 5) { $x = 5 }
  if ($a -eq 6) { $x = 6 }
  if ($a -eq 7) { $x = 7 }
  if ($a -eq 8) { $x = 8 }
  if ($a -eq 9) { $x = 9 }
  if ($a -eq 10) { $x = 10 }
  if ($a -eq 11) { $x = 11 }
  if ($a -eq 12) { $x = 12 }
  if ($a -eq 13) { $x = 13 }
  if ($a -eq 14) { $x = 14 }
  if ($a -eq 15) { $x = 15 }
  if ($a -eq 16) { $x = 16 }
  $x
}
